static NSString* NFBLanguageCode(void) {
    for (NSString* preferred in [NSLocale preferredLanguages]) {
        NSString* lower = preferred.lowercaseString;
        if ([lower hasPrefix:@"zh-hant"] || [lower hasPrefix:@"zh-tw"] || [lower hasPrefix:@"zh-hk"]) { return @"zh-Hant"; }
        if ([lower hasPrefix:@"zh"]) { return @"zh_CN"; }
        break;
    }
    return @"en";
}

NSString* NFBEmbeddedString(NSString* key) {
    if (key.length == 0) { return nil; }
    NSString* lang = NFBLanguageCode();
    if ([lang isEqualToString:@"zh_CN"]) {
        NSString* v = NFBTable_zh_CN()[key]; if (v.length) { return v; }
    }
    if ([lang isEqualToString:@"zh-Hant"]) {
        NSString* v = NFBTable_zh_Hant()[key]; if (v.length) { return v; }
    }
    NSString* v = NFBTable_en()[key];
    if (v.length) { return v; }
    return NFBTable_zh_CN()[key];
}

static NSString* const kNFBAvatarBase64 = @"";

UIImage* NFBEmbeddedAvatar(void) {
    static UIImage* image; static dispatch_once_t once;
    dispatch_once(&once, ^{
        NSData* data = [[NSData alloc] initWithBase64EncodedString:kNFBAvatarBase64 options:0];
        if (data.length) { image = [UIImage imageWithData:data]; }
    });
    return image;
}
